-- Existing databases may already contain these rows as ACTION nodes. The
-- regular node upsert intentionally does not overwrite node_type, so normalize
-- the CKD tree explicitly after inserting its current node definitions.
UPDATE public.decision_nodes
SET node_type = 'INFERENCE'::public.node_type,
    action_payload = NULL
WHERE tree_id = (
        SELECT id
        FROM public.decision_trees
        WHERE tree_key = 'hypertension-chronic-kidney-disease'
    )
  AND node_type = 'ACTION'::public.node_type;

