INSERT INTO public.symptoms (symptom_id, type, subgroup, name_vn, name_en, description_vn, description_en, source, icd10_code, snomed_code, loinc_code, loinc_common_name, decision_tree_vn, decision_tree_en)
VALUES ('SYM0001', 'Bệnh', 'Tăng huyết áp', 'Tăng huyết áp', 'Hypertensive diseases', 'Tình trạng huyết áp động mạch tăng cao mạn tính, là yếu tố nguy cơ chính của bệnh tim mạch, đột quỵ và bệnh thận mạn.', 'A chronic condition of elevated arterial blood pressure; a major risk factor for cardiovascular disease, stroke, and chronic kidney disease.', 'Mục 1.2.', 'I10-I15', '38341003', NULL, NULL, 'Chẩn đoán THA, Phân tầng nguy cơ tim mạch, Ngưỡng và đích điều trị, Điều trị thiết yếu, Điều trị tối ưu, Phối hợp thuốc, THA người cao tuổi, THA + Đái Tháo Đường týp 2, THA + Bệnh mạch vành, THA + Suy tim, THA + Bệnh thận mạn, THA trong thai kỳ, THA kháng trị, THA cấp cứu', 'Hypertension Diagnosis, Risk Classification, Treatment Threshold and BP Target, Essential treatment strategy, Optimal treatment strategy, Drug Combination, Hypertension older adults, Hypertension With Type 2 Diabetes, Hypertension + Coronary Artery Disease, Hypertension + Heart Failure, Hypertension With Chronic Kidney Disease, Hypertension in Pregnancy, Resistant Hypertension, Hypertensive Emergency')
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

INSERT INTO public.symptoms (symptom_id, type, subgroup, name_vn, name_en, description_vn, description_en, source, icd10_code, snomed_code, loinc_code, loinc_common_name, decision_tree_vn, decision_tree_en)
VALUES ('SYM0002', 'Bệnh', 'Tăng huyết áp', 'Tăng huyết áp nguyên phát', 'Primary Hypertension', 'Tăng huyết áp không xác định được nguyên nhân cụ thể, chiếm khoảng 90-95% các trường hợp THA.', 'Hypertension with no identifiable secondary cause, accounting for roughly 90-95% of hypertension cases.', 'Mục 1.2.', 'I10', '59621000', NULL, NULL, NULL, NULL)
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

INSERT INTO public.symptoms (symptom_id, type, subgroup, name_vn, name_en, description_vn, description_en, source, icd10_code, snomed_code, loinc_code, loinc_common_name, decision_tree_vn, decision_tree_en)
VALUES ('SYM0003', 'Bệnh', 'Tăng huyết áp', 'Tăng huyết áp thứ phát', 'Secondary Hypertension', 'Tăng huyết áp gây ra bởi một bệnh lý hoặc nguyên nhân xác định được (thận, nội tiết, mạch máu, thuốc...).', 'Hypertension caused by an identifiable underlying condition (renal, endocrine, vascular, or drug-related).', 'Mục 3.6.3.', 'I15', '31992008', NULL, NULL, NULL, NULL)
