VALUES ('SYM0005', 'Bệnh', 'Tăng huyết áp', 'Giả tăng huyết áp kháng trị', 'Pseudo-resistant Hypertension', 'Tình trạng huyết áp có vẻ kháng trị nhưng thực chất do đo sai kỹ thuật, hiệu ứng áo choàng trắng, hoặc không tuân thủ điều trị chứ không phải kháng trị thực sự.', 'Apparent treatment resistance actually caused by measurement errors, white-coat effect, or poor medication adherence rather than true pharmacological resistance.', 'Mục 3.6.1.', NULL, NULL, NULL, NULL, 'THA kháng trị', 'Resistant Hypertension')
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

