VALUES ('SYM0025', 'Bệnh', 'Bệnh đồng mắc', 'COVID-19', 'COVID-19', 'Bệnh nhiễm trùng đường hô hấp do virus SARS-CoV-2 gây ra.', 'A respiratory infectious disease caused by the SARS-CoV-2 virus.', 'Mục 3.6.4.', 'U07.1', '840539006', NULL, NULL, NULL, NULL)
