VALUES ('SYM0028', 'Bệnh', 'Nguyên nhân THA thứ phát', 'Bệnh nhu mô thận', 'Renal Parenchymal Disease', 'Tổn thương trực tiếp mô thận (cầu thận, ống thận, kẽ thận) gây tăng huyết áp thứ phát.', 'Direct damage to renal tissue (glomeruli, tubules, or interstitium) causing secondary hypertension.', 'Mục 3.6.3.', 'I15.1', '767094002', NULL, NULL, NULL, NULL)
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

INSERT INTO public.symptoms (symptom_id, type, subgroup, name_vn, name_en, description_vn, description_en, source, icd10_code, snomed_code, loinc_code, loinc_common_name, decision_tree_vn, decision_tree_en)
VALUES ('SYM0029', 'Bệnh', 'Nguyên nhân THA thứ phát', 'Hẹp động mạch thận', 'Renal Artery Stenosis', 'Hẹp lòng một hoặc cả hai động mạch thận, làm giảm tưới máu thận và kích hoạt trục renin-angiotensin gây THA.', 'Narrowing of one or both renal arteries, reducing renal perfusion and activating the renin-angiotensin axis, causing hypertension.', 'Mục 3.6.3.', 'I15.0', '302233006', NULL, NULL, 'Phối hợp thuốc', 'Drug Combination')
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

INSERT INTO public.symptoms (symptom_id, type, subgroup, name_vn, name_en, description_vn, description_en, source, icd10_code, snomed_code, loinc_code, loinc_common_name, decision_tree_vn, decision_tree_en)
VALUES ('SYM0030', 'Bệnh', 'Nguyên nhân THA thứ phát', 'Xơ vữa động mạch thận', 'Atherosclerotic Renal Artery Disease', 'Mảng xơ vữa tích tụ trong thành động mạch thận, nguyên nhân thường gặp nhất của hẹp động mạch thận ở người lớn tuổi.', 'Atherosclerotic plaque buildup in the wall of the renal artery, the most common cause of renal artery stenosis in older adults.', 'Mục 3.6.3.', 'I70.1', '45281005', NULL, NULL, NULL, NULL)
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

INSERT INTO public.symptoms (symptom_id, type, subgroup, name_vn, name_en, description_vn, description_en, source, icd10_code, snomed_code, loinc_code, loinc_common_name, decision_tree_vn, decision_tree_en)
VALUES ('SYM0031', 'Bệnh', 'Nguyên nhân THA thứ phát', 'Loạn sản cơ', 'Fibromuscular Dysplasia', 'Bệnh lý không do xơ vữa gây hẹp, phình hoặc bóc tách động mạch (thường động mạch thận), hay gặp ở phụ nữ trẻ.', 'A non-atherosclerotic vascular disease causing stenosis, aneurysm, or dissection of arteries (commonly renal), more common in young women.', 'Mục 3.6.3.', 'I77.3', '783729004', NULL, NULL, NULL, NULL)
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

