VALUES ('SYM0034', 'Bệnh', 'Nguyên nhân THA thứ phát', 'Hẹp eo động mạch chủ', 'Coarctation of Aorta', 'Hẹp bẩm sinh đoạn động mạch chủ, thường gây THA chi trên và mạch đùi yếu.', 'A congenital narrowing of a segment of the aorta, typically causing upper-limb hypertension and diminished femoral pulses.', 'Mục 3.6.3.', 'Q25.1', '7305005', NULL, NULL, NULL, NULL)
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

INSERT INTO public.symptoms (symptom_id, type, subgroup, name_vn, name_en, description_vn, description_en, source, icd10_code, snomed_code, loinc_code, loinc_common_name, decision_tree_vn, decision_tree_en)
VALUES ('SYM0035', 'Bệnh', 'Nguyên nhân THA thứ phát', 'Ngưng thở khi ngủ mạn tính', 'Obstructive Sleep Apnea', 'Rối loạn hô hấp khi ngủ với các đợt ngừng/giảm thở lặp lại do tắc nghẽn đường thở trên, liên quan chặt đến THA kháng trị.', 'A sleep-related breathing disorder with repeated apnea/hypopnea episodes due to upper airway obstruction, strongly associated with resistant hypertension.', 'Mục 3.6.3.', 'G47.3', '78275009', NULL, NULL, NULL, NULL)
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

INSERT INTO public.symptoms (symptom_id, type, subgroup, name_vn, name_en, description_vn, description_en, source, icd10_code, snomed_code, loinc_code, loinc_common_name, decision_tree_vn, decision_tree_en)
VALUES ('SYM0036', 'Bệnh', 'Bệnh đồng mắc', 'Phì đại thất trái', 'Left Ventricular Hypertrophy', 'Dày cơ thất trái, thường là hậu quả của THA mạn tính, một dấu hiệu tổn thương cơ quan đích.', 'Thickening of the left ventricular wall, typically a consequence of chronic hypertension and a marker of target-organ damage.', 'Mục 3.7.3., Bảng 20, Mục 1.3', 'I11.9', '55827005', NULL, NULL, 'THA + Suy tim, THA cấp cứu', 'Hypertension + Heart Failure, Hypertensive Emergency')
ON CONFLICT (symptom_id) DO UPDATE SET type = EXCLUDED.type, subgroup = EXCLUDED.subgroup, name_vn = EXCLUDED.name_vn, name_en = EXCLUDED.name_en, description_vn = EXCLUDED.description_vn, description_en = EXCLUDED.description_en, source = EXCLUDED.source, icd10_code = EXCLUDED.icd10_code, snomed_code = EXCLUDED.snomed_code, loinc_code = EXCLUDED.loinc_code, loinc_common_name = EXCLUDED.loinc_common_name, decision_tree_vn = EXCLUDED.decision_tree_vn, decision_tree_en = EXCLUDED.decision_tree_en;

